SELECT *
FROM employees
WHERE employee_id BETWEEN :id_min AND :id_max;

SELECT *
FROM products
WHERE unit_price BETWEEN :price_from AND :price_to;

SELECT city, COUNT(*)
FROM employees
GROUP BY city;

SELECT category, MAX(unit_price)
FROM products
GROUP BY category;

SELECT o.order_id, e.first_name, e.last_name
FROM orders o
INNER JOIN employees e ON o.employee_id = e.id;

SELECT c.company_name, c.city, e.first_name, e.last_name
FROM customers c
INNER JOIN employees e ON c.city = e.city;

SELECT product_name, unit_price
FROM products
ORDER BY unit_price;

SELECT product_id, product_name
FROM products
ORDER BY product_id;
